<template><view class="add-page"><view class="nav"><text @tap="back">‹</text><text>添加银行卡</text><view/></view><view class="body"><view class="tip">请绑定本人实名认证的储蓄卡</view><view class="form"><view><text>银行卡号</text><input v-model="cardNo" type="number" maxlength="19" placeholder="请输入银行卡卡号"/><text class="scan" @tap="scan">▣</text></view><view @tap="chooseBank"><text>开户银行</text><input :value="bank" disabled placeholder="请选择开户银行"/><text class="arrow">›</text></view></view><text class="hint">仅支持储蓄卡，银行卡信息将加密保护</text><button :disabled="!canContinue" @tap="continueVerify">下一步</button></view></view></template>
<script setup>import{computed,onMounted,ref}from'vue';import{enforcePortal}from'../../core/route-guard';const cardNo=ref(''),bank=ref('工商银行'),banks=['工商银行','中国农业银行','中国银行','上海银行','中国交通银行','招商银行'];onMounted(()=>enforcePortal('agent'));const canContinue=computed(()=>/^\d{13,19}$/.test(cardNo.value)&&bank.value);function back(){uni.navigateBack()}function scan(){uni.showToast({title:'银行卡识别功能待接入',icon:'none'})}function chooseBank(){uni.showActionSheet({itemList:banks,success:r=>bank.value=banks[r.tapIndex]})}function continueVerify(){uni.navigateTo({url:`/pages/agent/verify-bank-card?bank=${encodeURIComponent(bank.value)}&cardNo=${cardNo.value}`})}</script>
<style lang="scss" scoped>.add-page{min-height:100vh;background:#f7f8fc;color:#28334c}.nav{display:flex;justify-content:space-between;align-items:center;height:calc(102rpx + env(safe-area-inset-top));padding:env(safe-area-inset-top) 32rpx 0;background:#fff;box-sizing:border-box;font-size:30rpx;font-weight:720}.nav text:first-child{width:60rpx;color:#5966f3;font-size:60rpx;line-height:1}.nav view{width:60rpx}.body{padding:37rpx 34rpx}.tip{padding:20rpx 23rpx;border-radius:16rpx;background:#eef0ff;color:#6875a2;font-size:22rpx}.form{margin-top:24rpx;padding:7rpx 28rpx;border-radius:23rpx;background:#fff}.form>view{position:relative;display:flex;align-items:center;padding:27rpx 0;border-bottom:1rpx solid #eceef3}.form>view:last-child{border:0}.form>view>text:first-child{width:126rpx;font-size:25rpx;font-weight:650}.form input{flex:1;height:48rpx;color:#68748b;font-size:24rpx}.scan,.arrow{position:absolute!important;right:0!important;width:auto!important;color:#5966f3;font-size:29rpx!important}.arrow{font-size:38rpx!important}.hint{display:block;margin:22rpx 4rpx;color:#9aa3b2;font-size:21rpx}.body button{width:100%;margin-top:42rpx;border:0;border-radius:16rpx;background:#5966f3;color:#fff;font-size:27rpx;line-height:88rpx}.body button[disabled]{background:#c6cbd8}.body button::after{border:0}</style>
